108	// Root returns the root content node of a document (nil if empty).
109	func (n *Node) Root() *Node {
110		if n.Kind == DocumentKind {
111			if len(n.Content) == 0 {
112				return nil
113			}
114			return n.Content[0]
115		}
116		return n
117	}
