// Package propsp implements a Java .properties decoder and encoder.
//
// Decode turns a properties file into a document tree: keys are split on
// "." into nested maps, numeric path segments create (sparse) arrays, and
// all values are !!str scalars (no auto-parsing of numbers/booleans).
//
// Encode flattens a document tree back into key/value lines, joining nested
// keys with "." and array indexes either with "." (default) or with "[i]"
// (when --properties-array-brackets is set).
package propsp

import (
	"fmt"
	"io"
	"strconv"
	"strings"

	"yq/node"
	"yq/settings"
)

// isSpace reports whether c is properties whitespace (key terminator and
// ignorable around separators). Mirrors java.util.Properties: space, tab
// and form feed.
func isSpace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\f'
}

// logicalLine is one logical properties line (continuations joined).
type logicalLine struct {
	text string
	line int // 1-based number of the physical line it started on
}

// splitPhysical splits data into physical lines on \r\n, \n or \r.
func splitPhysical(data string) []string {
	var lines []string
	start := 0
	for i := 0; i < len(data); i++ {
		if data[i] == '\n' || data[i] == '\r' {
			lines = append(lines, data[start:i])
			if data[i] == '\r' && i+1 < len(data) && data[i+1] == '\n' {
				i++
			}
			start = i + 1
		}
	}
	if start < len(data) {
		lines = append(lines, data[start:])
	}
	return lines
}

// logicalLines joins physical lines ending in an odd number of backslashes
// with the following line (one backslash removed, leading whitespace of the
// continuation skipped).
func logicalLines(data string) []logicalLine {
	phys := splitPhysical(data)
	var out []logicalLine
	for i := 0; i < len(phys); i++ {
		text := phys[i]
		startLine := i + 1
		for hasContinuation(text) && i+1 < len(phys) {
			text = text[:len(text)-1] // drop the continuation backslash
			i++
			text += strings.TrimLeft(phys[i], " \t\f")
		}
		out = append(out, logicalLine{text: text, line: startLine})
	}
	return out
}

// hasContinuation reports whether the line ends with an odd number of
// backslashes.
func hasContinuation(s string) bool {
	n := 0
	for i := len(s) - 1; i >= 0 && s[i] == '\\'; i-- {
		n++
	}
	return n%2 == 1
}

// unescape processes properties escape sequences: \t \n \r \f \\ \uXXXX and
// \<any other char> which yields the char itself.
func unescape(s string, line int) (string, error) {
	if !strings.Contains(s, "\\") {
		return s, nil
	}
	var b strings.Builder
	b.Grow(len(s))
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c != '\\' {
			b.WriteByte(c)
			continue
		}
		i++
		if i >= len(s) {
			b.WriteByte('\\')
			break
		}
		switch s[i] {
		case 't':
			b.WriteByte('\t')
		case 'n':
			b.WriteByte('\n')
		case 'r':
			b.WriteByte('\r')
		case 'f':
			b.WriteByte('\f')
		case '\\':
			b.WriteByte('\\')
		case 'u':
			if i+4 >= len(s) {
				return "", fmt.Errorf("properties: Line %d: invalid unicode literal", line)
			}
			v, err := strconv.ParseUint(s[i+1:i+5], 16, 32)
			if err != nil {
				return "", fmt.Errorf("properties: Line %d: invalid unicode literal", line)
			}
			b.WriteRune(rune(v))
			i += 4
		default:
			b.WriteByte(s[i])
		}
	}
	return b.String(), nil
}

// parseLine splits a logical line into key and value, processing escapes.
// ok is false for blank lines and comments (# or !).
func parseLine(l logicalLine) (key, value string, ok bool, err error) {
	s := strings.TrimLeft(l.text, " \t\f")
	if s == "" || s[0] == '#' || s[0] == '!' {
		return "", "", false, nil
	}
	// Find the end of the key: first unescaped '=', ':' or whitespace.
	i := 0
	for i < len(s) {
		c := s[i]
		if c == '\\' {
			i += 2
			continue
		}
		if c == '=' || c == ':' || isSpace(c) {
			break
		}
		i++
	}
	rawKey := s[:i]
	rest := s[i:]
	// Skip whitespace, then an optional '=' or ':' plus following whitespace.
	j := 0
	for j < len(rest) && isSpace(rest[j]) {
		j++
	}
	if j < len(rest) && (rest[j] == '=' || rest[j] == ':') {
		j++
		for j < len(rest) && isSpace(rest[j]) {
			j++
		}
	}
	value, err = unescape(rest[j:], l.line)
	if err != nil {
		return "", "", false, err
	}
	key, err = unescape(rawKey, l.line)
	if err != nil {
		return "", "", false, err
	}
	if key == "" {
		return "", "", false, fmt.Errorf("properties: Line %d: %q", l.line, value)
	}
	return key, value, true, nil
}

// newContainer creates the intermediate node for a missing path segment: an
// array when the next segment parses as an integer, a map otherwise.
func newContainer(nextSegment string) *node.Node {
	if _, err := strconv.ParseInt(nextSegment, 10, 64); err == nil {
		return node.NewSequence()
	}
	return node.NewMapping()
}

// setPath assigns value at the dotted path under root, creating intermediate
// maps/arrays as needed. Traversal into an existing scalar is silently
// ignored; indexing an existing array with a non-numeric key errors.
func setPath(root *node.Node, path []string, value string) error {
	cur := root
	for i, seg := range path {
		last := i == len(path)-1
		switch cur.Kind {
		case node.MappingKind:
			if last {
				cur.MapSet(node.NewString(seg), node.NewString(value))
				return nil
			}
			child := cur.MapValue(seg)
			if child == nil {
				child = newContainer(path[i+1])
				cur.MapSet(node.NewString(seg), child)
			}
			if child.Kind == node.ScalarKind {
				return nil
			}
			cur = child
		case node.SequenceKind:
			idx64, err := strconv.ParseInt(seg, 10, 64)
			if err != nil {
				return fmt.Errorf("cannot index array with '%s' (%v)", seg, err)
			}
			idx := int(idx64)
			if idx < 0 {
				return fmt.Errorf("index [%d] out of range, array size is %d", idx, len(cur.Content))
			}
			for len(cur.Content) <= idx {
				cur.Content = append(cur.Content, node.NewNull())
			}
			if last {
				cur.Content[idx] = node.NewString(value)
				return nil
			}
			child := cur.Content[idx]
			if child.Kind == node.ScalarKind {
				if !child.IsNull() {
					return nil
				}
				child = newContainer(path[i+1])
				cur.Content[idx] = child
			}
			cur = child
		default:
			return nil
		}
	}
	return nil
}

// Decode parses properties data into a single document node.
func Decode(data []byte, s *settings.Settings) ([]*node.Node, error) {
	if len(data) == 0 {
		// Empty input yields a document holding an empty null scalar.
		return []*node.Node{node.NewDocument(node.NewScalar("!!null", ""))}, nil
	}
	root := node.NewMapping()
	for _, l := range logicalLines(string(data)) {
		key, value, ok, err := parseLine(l)
		if err != nil {
			return nil, err
		}
		if !ok {
			continue
		}
		if err := setPath(root, strings.Split(key, "."), value); err != nil {
			return nil, err
		}
	}
	return []*node.Node{node.NewDocument(root)}, nil
}

// escapeKey escapes a flattened key for output: backslash, control
// characters, and (unlike values) spaces and colons anywhere in the key.
func escapeKey(k string) string {
	var b strings.Builder
	b.Grow(len(k))
	for i := 0; i < len(k); i++ {
		switch k[i] {
		case '\\':
			b.WriteString("\\\\")
		case '\t':
			b.WriteString("\\t")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\f':
			b.WriteString("\\f")
		case ' ':
			b.WriteString("\\ ")
		case ':':
			b.WriteString("\\:")
		default:
			b.WriteByte(k[i])
		}
	}
	return b.String()
}

// escapeValue escapes a value for output: backslash and control characters
// anywhere, plus a single leading space.
func escapeValue(v string) string {
	var b strings.Builder
	b.Grow(len(v))
	for i := 0; i < len(v); i++ {
		switch v[i] {
		case '\\':
			b.WriteString("\\\\")
		case '\t':
			b.WriteString("\\t")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\f':
			b.WriteString("\\f")
		case ' ':
			if i == 0 {
				b.WriteString("\\ ")
			} else {
				b.WriteByte(' ')
			}
		default:
			b.WriteByte(v[i])
		}
	}
	return b.String()
}

// writeNode flattens n into properties lines under the given key prefix.
func writeNode(b *strings.Builder, n *node.Node, prefix, sep string, brackets bool) {
	switch n.Kind {
	case node.DocumentKind:
		if root := n.Root(); root != nil {
			writeNode(b, root, prefix, sep, brackets)
		}
	case node.AliasKind:
		if n.Alias != nil {
			writeNode(b, n.Alias, prefix, sep, brackets)
		}
	case node.MappingKind:
		for i := 0; i+1 < len(n.Content); i += 2 {
			key := n.Content[i].Value
			p := key
			if prefix != "" {
				p = prefix + "." + key
			}
			writeNode(b, n.Content[i+1], p, sep, brackets)
		}
	case node.SequenceKind:
		for i, el := range n.Content {
			var p string
			switch {
			case prefix == "":
				p = strconv.Itoa(i)
			case brackets:
				p = prefix + "[" + strconv.Itoa(i) + "]"
			default:
				p = prefix + "." + strconv.Itoa(i)
			}
			writeNode(b, el, p, sep, brackets)
		}
	default: // ScalarKind
		if prefix == "" {
			// A scalar document root is printed bare, without escaping.
			b.WriteString(n.Value)
			b.WriteString("\n")
			return
		}
		b.WriteString(escapeKey(prefix))
		b.WriteString(sep)
		b.WriteString(escapeValue(n.Value))
		b.WriteString("\n")
	}
}

// Encode writes the result nodes as properties text. Empty maps/sequences
// produce no output; multiple documents are concatenated with no separator.
func Encode(w io.Writer, nodes []*node.Node, s *settings.Settings) error {
	for _, n := range nodes {
		var b strings.Builder
		writeNode(&b, n, "", s.PropsSeparator, s.PropsArrayBrackets)
		out := b.String()
		if s.NulOutput && strings.HasSuffix(out, "\n") {
			out = out[:len(out)-1] + "\x00"
		}
		if _, err := io.WriteString(w, out); err != nil {
			return err
		}
	}
	return nil
}

