// dump renders a node tree in a canonical s-expression-ish form so tests
// can assert on exact structure (kinds, tags, order, null fillers).
func dump(n *node.Node) string {
	if n == nil {
		return "<nil>"
	}
	switch n.Kind {
	case node.DocumentKind:
		if len(n.Content) == 0 {
			return "doc()"
		}
		return "doc(" + dump(n.Content[0]) + ")"
	case node.MappingKind:
		var b strings.Builder
		b.WriteString("{")
		for i := 0; i+1 < len(n.Content); i += 2 {
			if i > 0 {
				b.WriteString(" ")
			}
			b.WriteString(strconv_(n.Content[i].Value))
			b.WriteString("=")
			b.WriteString(dump(n.Content[i+1]))
		}
		b.WriteString("}")
		return b.String()
	case node.SequenceKind:
		var b strings.Builder
		b.WriteString("[")
		for i, el := range n.Content {
			if i > 0 {
				b.WriteString(" ")
			}
			b.WriteString(dump(el))
		}
		b.WriteString("]")
		return b.String()
	default:
		return n.Tag + ":" + strconv_(n.Value)
	}
}

func strconv_(s string) string {
	return "\"" + strings.ReplaceAll(s, "\"", "\\\"") + "\""
}

func decodeRoot(t *testing.T, input string) *node.Node {
	t.Helper()
	docs, err := Decode([]byte(input), settings.New())
