func encode(t *testing.T, n *node.Node, mutate func(*settings.Settings)) string {
	t.Helper()
	s := settings.New()
	if mutate != nil {
		mutate(s)
	}
	var b strings.Builder
	if err := Encode(&b, []*node.Node{n}, s); err != nil {
		t.Fatalf("Encode error: %v", err)
	}
	return b.String()
}

// buildMap is a small helper: buildMap("k1", v1, "k2", v2, ...).
func buildMap(pairs ...interface{}) *node.Node {
	m := node.NewMapping()
	for i := 0; i < len(pairs); i += 2 {
		m.Content = append(m.Content, node.NewString(pairs[i].(string)), pairs[i+1].(*node.Node))
	}
	return m
}

func seq(els ...*node.Node) *node.Node {
	s := node.NewSequence()
	s.Content = append(s.Content, els...)
	return s
}

func TestEncodeBasic(t *testing.T) {
	n := buildMap("a", buildMap("b", node.NewScalar("!!int", "1"), "c", node.NewString("x")))
