	if got := encode(t, node.NewString(" x"), nil); got != " x\n" {
		t.Errorf("leading space root: got %q", got)
	}
	if got := encode(t, node.NewNull(), nil); got != "null\n" {
		t.Errorf("null root: got %q", got)
