func TestRoundTrip(t *testing.T) {
	input := "a.b = 1\na.c = x\n"
	docs, err := Decode([]byte(input), settings.New())
	if err != nil {
		t.Fatal(err)
	}
	if got := encode(t, docs[0].Root(), nil); got != input {
		t.Errorf("got %q, want %q", got, input)
	}
}

