package propsp

import (
	"os/exec"
	"strings"
	"testing"

	"yq/settings"
)

// Temporary differential test: compares my Decode+Encode against the
// original binary's `-p props -o props` pipeline.
func TestDifferentialAgainstOriginal(t *testing.T) {
	inputs := []string{
		"a.b.c=1\na.b.d=2\n",
		"a.0=x\na.1=y\n",
		"a.2=x\n",
		"a.0.b=x\na.1.c.d=y\n",
		"a: 1\nb = 2\nc 3\nd\n",
		"# c\n! b\n\na=1\n",
		"a\\=b=c\na\\:b2=d\na\\ b3=e\n",
		"k\\:ey=v\\:al\na=\\t\\n\\r\\f\\\\\nb=\\u0041BC\nc=\\q\n",
		"a=one\\\n   two\n",
		"a=1\r\nb=2\rc=3\n",
		"a\fb=1\nc\td=2\n",
		"b=1\na=2\nb=3\n",
		"a..b=1\n.a=2\nc.=3\n",
		"a.01=x\nb.+1=y\nc.-0=z\n",
		"a.b=y\na.0=x\n",
		"1.5=x\n",
		"a.b=1\na.b.c=2\nc=3\nc.d=4\n",
		"a.b.c=1\na.b=2\nd.0=x\nd=1\n",
		"a=héllo😀\n",
		"key = value with spaces \nempty=\n",
		"true=1\nnull=n\n1=x\n",
	}
	for _, brackets := range []string{"", "--properties-array-brackets"} {
		for _, input := range inputs {
			args := []string{"-p", "props", "-o", "props"}
			if brackets != "" {
				args = append(args, brackets)
			}
			cmd := exec.Command("/workspace/executable", args...)
			cmd.Stdin = strings.NewReader(input)
			out, err := cmd.CombinedOutput()
			if err != nil {
				t.Fatalf("binary failed on %q: %v\n%s", input, err, out)
			}
			docs, derr := Decode([]byte(input), settings.New())
			if derr != nil {
				t.Fatalf("Decode(%q) error: %v", input, derr)
			}
			s := settings.New()
			s.PropsArrayBrackets = brackets != ""
			var b strings.Builder
			if eerr := Encode(&b, []*node_{docs[0].Root()}, s); eerr != nil {
				t.Fatalf("Encode(%q) error: %v", input, eerr)
			}
			if b.String() != string(out) {
				t.Errorf("input %q (brackets=%v):\n mine: %q\norig: %q", input, brackets != "", b.String(), string(out))
			}
		}
	}
}
